contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger) public {
        bool approvalReverted;
        bool approvalChangedBefore;
        approvalChangedBefore = c.approvedToLog(logger);
        try c.setApprovedLogger(logger, true) { approvalReverted = false; }
        catch { approvalReverted = true; }
        bool logResult = c.logRedeemed(bytes32(uint256(1)));
        bool changedAfter = c.approvedToLog(logger);
        assert(approvalReverted && !approvalChangedBefore && !changedAfter && !logResult);
    }
    receive() external payable {}
}
